import{_ as o,c as a,a2 as e,o as u}from"./chunks/framework.BQmytedh.js";const h=JSON.parse('{"title":"人生与人心","description":"","frontmatter":{},"headers":[],"relativePath":"哲思_人文_社科/博主_频道/陈果/人生与人心.md","filePath":"哲思_人文_社科/博主_频道/陈果/人生与人心.md","lastUpdated":1733938304000}'),q={name:"哲思_人文_社科/博主_频道/陈果/人生与人心.md"};function r(p,t,i,s,d,l){return u(),a("div",null,t[0]||(t[0]=[e('<h1 id="人生与人心" tabindex="-1">人生与人心 <a class="header-anchor" href="#人生与人心" aria-label="Permalink to &quot;人生与人心&quot;">​</a></h1><p>【复旦大学《人生与人心》陈果教授（46集全）】 <a href="https://www.bilibili.com/video/BV1DL411X7ZN/?p=6&amp;share_source=copy_web&amp;vd_source=dbdac2a7096f7d2656e413a441bd7afe" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1DL411X7ZN/?p=6&amp;share_source=copy_web&amp;vd_source=dbdac2a7096f7d2656e413a441bd7afe</a></p><h2 id="_1-2-什么是完整的-大人" tabindex="-1">1.2 什么是完整的 &quot;大人&quot; <a class="header-anchor" href="#_1-2-什么是完整的-大人" aria-label="Permalink to &quot;1.2 什么是完整的 &quot;大人&quot;&quot;">​</a></h2><p>独立之人格, 自由之思想. -- 陈寅恪</p><p>&quot;而我后面加上一个我自己个人的观点: 责任之担当&quot; -- 陈果</p><h2 id="_1-4-何为-自由" tabindex="-1">1.4 何为 &quot;自由&quot; <a class="header-anchor" href="#_1-4-何为-自由" aria-label="Permalink to &quot;1.4 何为 &quot;自由&quot;&quot;">​</a></h2><p>自由是有所为而有所不为</p><p>&quot;人类的节制比放纵更接近自由&quot; -- 歌德 &lt;德&gt;</p><p>find myself 发现自己</p><p>try to be myself 努力成为我所是</p><p>&quot;自由是带着枷锁舞蹈&quot; -- 卢梭</p><p>&quot;自由不是让你想做什么就做什么，自由是教你不想做什么，就可以不做什么。&quot; -- 康德</p><h2 id="_2-2-何谓-大师" tabindex="-1">2.2 何谓 &quot;大师&quot; ? <a class="header-anchor" href="#_2-2-何谓-大师" aria-label="Permalink to &quot;2.2 何谓 &quot;大师&quot; ?&quot;">​</a></h2><p>真诚</p><p>&quot;<strong>净极光通达</strong>&quot;</p><p>&quot;人格魅力&quot; 重点在 &quot;人格&quot; 二字</p><h2 id="_2-4-知识分子当是社会的良知" tabindex="-1">2.4 &quot;知识分子当是社会的良知&quot; <a class="header-anchor" href="#_2-4-知识分子当是社会的良知" aria-label="Permalink to &quot;2.4 &quot;知识分子当是社会的良知&quot;&quot;">​</a></h2><p>对自己倾诉 为自己写信 &quot;Dear me: &quot;</p><p>在陈果老师迷茫之时, 她的导师张庆熊回信: &quot;陈果, 不管你将来从事何种职业, 希望你能尽心尽力. 你需要记住一点: <strong>知识分子当是社会的良知</strong>.&quot;</p><p>&quot;尽心尽力不是说你要对这件事本身付多少责任, 而是说既然你要花时间去做这些事, 不要辜负了这些时间, 不要辜负了度过这段时间的那个你.&quot;</p><h2 id="_2-5-大学-与-大人-的历史渊源" tabindex="-1">2.5 &quot;大学&quot; 与 &quot;大人&quot; 的历史渊源 <a class="header-anchor" href="#_2-5-大学-与-大人-的历史渊源" aria-label="Permalink to &quot;2.5 &quot;大学&quot; 与 &quot;大人&quot; 的历史渊源&quot;">​</a></h2><p>&quot;然后我喜欢一个法国的作家叫夏尔波德莱尔, 然后他有一句话我印象很深. 他说这世界上只有两件有价值的事: <strong>第一, 你要获得幸福; 第二, 你要使人幸福</strong>.&quot;</p><p>即</p><p>&quot;第一, 请你好好活着; 第二, 请你在自己好好活着的同时, 帮助别人好好活着.&quot;</p><p>这是孔子在73岁去世的时候说的: &quot;大节无亏, 可以安然去也.&quot;</p><p>&quot;什么叫大节无亏，就是这辈子你没有一个必须要说的谢谢，因为你没有亏欠谁；这辈子也没有一个必须要说的对不起，因为你没有伤害谁。&quot;</p><h2 id="_3-1-为什么我们需要自我认知" tabindex="-1">3.1 为什么我们需要自我认知 <a class="header-anchor" href="#_3-1-为什么我们需要自我认知" aria-label="Permalink to &quot;3.1 为什么我们需要自我认知&quot;">​</a></h2><p>世界的肚脐眼--古希腊的雅典</p><p>德尔菲神庙, 供奉太阳神阿波罗</p><p>&quot;人啊, 认识你自己&quot; -- 德尔菲神谕</p><p>犹太人问他们的神: &quot;你到底是谁?&quot;, &quot;Who are you?&quot;. 犹太人的神耶和华的回答是: &quot;I am who I am.&quot; &quot;我就是我, 我就是我所是.&quot;</p>',31)]))}const _=o(q,[["render",r]]);export{h as __pageData,_ as default};
